// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(bytes32 assertionId) public {
        // The reference C allows the call because msg.sender is the optimistic asserter
        // The mutant reverts due to require(false)
        try c.assertionDisputedCallback(assertionId) {
            // If no revert, the rule passes
            assertTrue(true);
        } catch {
            // If revert, the rule fails
            assertTrue(false);
        }
    }
}

